export function assertTimeZone(timeZone: string): void {
  new Intl.DateTimeFormat(\"en-US\", { timeZone });
}

function localParts(reference: Date, timeZone: string) {
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone,
    year: \"numeric\",
    month: \"2-digit\",
    day: \"2-digit\",
    hour: \"2-digit\",
