/** The calendar date of an instant on the workspace clock. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  const { year, month, day } = localParts(parseIso(value), timeZone);
  return `${String(year).padStart(4, "0")}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

// Represent a wall clock as UTC solely for calendar arithmetic, never as an
// actual instant. Intl supplies the offsets on both sides of a transition.
function wallClock(reference: Date, timeZone: string): number {
  const p = localParts(reference, timeZone);
  const wall = new Date(0);
  wall.setUTCFullYear(p.year, p.month - 1, p.day);
  wall.setUTCHours(p.hour, p.minute, p.second, reference.getUTCMilliseconds());
  return wall.getTime();
}

function localInstants(wall: number, timeZone: string): number[] {
  const offsets = new Set<number>();
  for (const days of [-2, -1, 0, 1, 2]) {
    const sample = wall + days * DAY_MS;
    offsets.add(wallClock(new Date(sample), timeZone) - sample);
  }
  const candidates = [...offsets].map((offset) => wall - offset);
  const exact = candidates.filter((instant) =>
    wallClock(new Date(instant), timeZone) === wall,
  ).sort((a, b) => a - b);
  if (exact.length > 0) return exact;

  // A skipped clock time is moved forward by the gap, as with calendar date
  // arithmetic. A repeated clock time has both instants returned above.
  const after = candidates.filter((instant) =>
    wallClock(new Date(instant), timeZone) > wall,
  ).sort((a, b) => a - b);
  return [after[0]];
}

/** The first instant of the local calendar day containing reference. */
export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  const wall = new Date(wallClock(reference, timeZone));
  wall.setUTCHours(0, 0, 0, 0);
  return toIsoTimestamp(new Date(localInstants(wall.getTime(), timeZone)[0]));
}

/** Moves by calendar days, preserving the local clock time across DST. */
export function addLocalDays(
  value: IsoTimestamp,
  days: number,
  timeZone: string,
): IsoTimestamp {
  const wall = new Date(wallClock(parseIso(value), timeZone));
  wall.setUTCDate(wall.getUTCDate() + days);
  return toIsoTimestamp(new Date(localInstants(wall.getTime(), timeZone)[0]));
}

/** A due date becomes overdue only after its local calendar day ends. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  return localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/** The previous calendar day'"'s window, anchored at the local digest hour. */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = \"UTC\",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if ("'!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const wall = new Date(wallClock(reference, timeZone));
  wall.setUTCHours(digestHourUtc, 0, 0, 0);
  let ends = localInstants(wall.getTime(), timeZone)
    .filter((instant) => instant <= reference.getTime());
  if (ends.length === 0) {
    wall.setUTCDate(wall.getUTCDate() - 1);
    ends = localInstants(wall.getTime(), timeZone);
  }
  const end = ends[ends.length - 1];
  wall.setUTCDate(wall.getUTCDate() - 1);

  return {
    start: toIsoTimestamp(new Date(localInstants(wall.getTime(), timeZone)[0])),
    end: toIsoTimestamp(new Date(end)),
  };
}
