    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe(\"Asia/Tokyo\");
    expect((await orgRepo.findOrgBySlug(tenant.org.slug))?.settings.timeZone).toBe(\"Asia/Tokyo\");
    expect((await orgRepo.listOrgsForUser(tenant.userIds.owner))[0].settings.timeZone).toBe(\"Asia/Tokyo\");
    for (const update of [
      () => orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, name: \"Changed\", settings: { timeZone: \"Unknown/Zone\" } }),
      () => orgService.updateOrganization(tenant.actors.owner, { orgId: tenant.org.id, name: \"Changed\", settings: { timeZone: \"Unknown/Zone\" } }),
    ]) {
      await expect(update()).rejects.toBeInstanceOf(RangeError);
      expect(await orgRepo.findOrgById(tenant.org.id)).toEqual(updated);
