    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { requireTwoFactor: true } });
    expect((await orgRepo.findOrgById(tenant.org.id))?.settings.timeZone).toBe(\"Asia/Tokyo\");
  });

  it(\"uses the same local-day rule for overdue events and both project stats endpoints\", async () => {
