    const today = await insert(\"2026-06-01T15:00:00.000Z\");
    const done = await insert(\"2026-06-01T01:00:00.000Z\");
    const canceled = await insert(\"2026-06-01T01:00:00.000Z\");
    const archived = await insert(\"2026-06-01T01:00:00.000Z\");
    await insert(null);
    await issueRepo.setIssueStatus(tenant.org.id, done.id, \"done\");
    await issueRepo.setIssueStatus(tenant.org.id, canceled.id, \"canceled\");
    await issueRepo.archiveIssue(tenant.org.id, archived.id);

    const seen: string[] = [];
    const off = subscribe(\"issue.overdue\", (payload) => {
      if (payload.orgId === tenant.org.id) seen.push(payload.issueId);
    });
    vi.useFakeTimers();
    try {
      vi.setSystemTime(new Date(\"2026-06-01T14:59:59.999Z\"));
      const before = await projectService.getProject(tenant.actors.owner, tenant.org.id, tenant.project.slug);
      expect(before.stats.overdueIssues).toBe(0);
      await runOverdueIssueJob(new Date());
      expect(seen).toEqual([]);

      vi.setSystemTime(new Date(\"2026-06-01T15:00:00.000Z\"));
      const detail = await projectService.getProject(tenant.actors.owner, tenant.org.id, tenant.project.slug);
      const list = await projectService.listProjects(tenant.actors.owner, { orgId: tenant.org.id, limit: 20 });
      expect(detail.stats.overdueIssues).toBe(1);
      expect(list.items[0].stats.overdueIssues).toBe(1);
      expect(detail.stats).toMatchObject({ openIssues: 3, closedIssues: 2 });
      await runOverdueIssueJob(new Date());
      expect(seen).toEqual([late.id]);
      expect(seen).not.toContain(today.id);
    } finally { off(); }
  });

  it.each([
    [\"Asia/Tokyo\", \"2026-01-15T12:00:00.000Z\", \"2025-12-15T15:00:00.000Z\"],
    [\"America/New_York\", \"2026-11-15T16:00:00.000Z\", \"2026-10-16T04:00:00.000Z\"],
    [\"America/New_York\", \"2026-03-22T16:00:00.000Z\", \"2026-02-20T05:00:00.000Z\"],
  ])(\"retains activity through local midnight %s at %s\", async (timeZone, reference, expectedCutoff) => {
    const tenant = await createTenant("'`retention-${reference.slice(0, 10)}`, "free");
    await orgRepo.updateOrg(tenant.org.id, { orgId: tenant.org.id, settings: { timeZone } });
    await usageRepo.recomputeUsage(tenant.org.id);
    const cutoff = new Date(expectedCutoff);
    const insert = (instant: Date) => activityRepo.insertActivity({
      orgId: tenant.org.id, action: "issue.created", actorId: null,
      subjectKind: "issue", subjectId: "issue", projectId: tenant.project.id,
      summary: "Retention boundary", metadata: {}, occurredAt: toIsoTimestamp(instant),
    });
    await insert(new Date(cutoff.getTime() - 1));
    const atCutoff = await insert(cutoff);
    const afterCutoff = await insert(new Date(cutoff.getTime() + 1));
    const purgeSpy = vi.spyOn(activityRepo, "purgeActivityBefore");
    const deleteSpy = vi.spyOn(searchRepo, "deleteSearchDocument");
    const archived = await issueRepo.insertIssue(issueInput(tenant.org.id, tenant.project.id), tenant.userIds.owner, 1);
    vi.useFakeTimers();
    vi.setSystemTime(new Date(cutoff.getTime() + 1));
    await issueRepo.archiveIssue(tenant.org.id, archived.id);
    vi.useRealTimers();

    await runCleanupArchivedJob(new Date(reference));
    expect(purgeSpy).toHaveBeenCalledWith(tenant.org.id, expectedCutoff);
    expect(deleteSpy).not.toHaveBeenCalledWith(tenant.org.id, "issue", archived.id);
    const remaining = await activityRepo.listActivityForSubject(tenant.org.id, "issue", "issue");
    expect(remaining.map((row) => row.id)).toEqual([afterCutoff.id, atCutoff.id]);
  });
});
